<?php
require 'config.php';require 'includes/functions.php';$pdo=db();$action=$_GET['action']??'list';$id=(int)($_GET['id']??0);$errors=[];$m=['full_name'=>'','email'=>'','phone'=>'','student_code'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$fa=$_POST['form_action']??'';if($fa==='delete'){try{$s=$pdo->prepare('DELETE FROM members WHERE id=?');$s->execute([(int)$_POST['id']]);flash('success','Member deleted.');}catch(Throwable $e){flash('danger','This member has loan history and cannot be deleted.');}redirect('members.php');}
$id=(int)($_POST['id']??0);foreach(array_keys($m) as $k)$m[$k]=trim($_POST[$k]??'');if($m['full_name']==='')$errors[]='Name is required.';if(!filter_var($m['email'],FILTER_VALIDATE_EMAIL))$errors[]='Valid email required.';if($m['student_code']==='')$errors[]='Member code required.';
if(!$errors){try{if($fa==='update'){$s=$pdo->prepare('UPDATE members SET full_name=?,email=?,phone=?,student_code=? WHERE id=?');$s->execute([$m['full_name'],$m['email'],$m['phone'],$m['student_code'],$id]);flash('success','Member updated.');}else{$s=$pdo->prepare('INSERT INTO members(full_name,email,phone,student_code) VALUES(?,?,?,?)');$s->execute([$m['full_name'],$m['email'],$m['phone'],$m['student_code']]);flash('success','Member registered.');}redirect('members.php');}catch(PDOException $e){$errors[]='Email and member code must be unique.';}}$action=$fa==='update'?'edit':'add';}
if($action==='edit'&&$id&&$_SERVER['REQUEST_METHOD']!=='POST'){$s=$pdo->prepare('SELECT * FROM members WHERE id=?');$s->execute([$id]);$found=$s->fetch();if($found)$m=$found;else{flash('warning','Member not found.');redirect('members.php');}}
$q=trim($_GET['q']??'');if($action==='list'){$sql='SELECT * FROM members';$params=[];if($q!==''){$sql.=' WHERE full_name LIKE ? OR email LIKE ? OR student_code LIKE ?';$t="%$q%";$params=[$t,$t,$t];}$sql.=' ORDER BY full_name';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();}
$pageTitle='Members';require 'includes/header.php'; ?>
<?php if(in_array($action,['add','edit'])): ?><div class="heading"><div><h1><?= $action==='edit'?'Edit member':'Register a member' ?></h1><p>Maintain reader details.</p></div><a href="members.php" class="btn btn-outline-secondary">Back</a></div><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $er)echo '<div>'.e($er).'</div>'; ?></div><?php endif; ?>
<form method="post" class="panel"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="form_action" value="<?= $action==='edit'?'update':'create' ?>"><input type="hidden" name="id" value="<?= $id ?>"><div class="row g-3">
<?php foreach(['full_name'=>'Full name','email'=>'Email','phone'=>'Phone','student_code'=>'Member code'] as $k=>$label): ?><div class="col-md-6"><label class="form-label"><?= e($label) ?><?= $k!=='phone'?' *':'' ?></label><input class="form-control" name="<?= e($k) ?>" <?= $k==='email'?'type="email"':'' ?> <?= $k!=='phone'?'required':'' ?> value="<?= e((string)$m[$k]) ?>"></div><?php endforeach; ?></div><button class="btn btn-primary mt-4">Save member</button></form>
<?php else: ?><div class="heading"><div><h1>Members</h1><p>Register and manage readers.</p></div><a class="btn btn-primary" href="members.php?action=add">+ Add member</a></div><form class="search mb-3" method="get"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Search name, email or member code"><button class="btn btn-outline-primary">Search</button></form><div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Member code</th><th>Actions</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><?= e($r['full_name']) ?></td><td><?= e($r['email']) ?></td><td><?= e($r['phone']) ?></td><td><?= e($r['student_code']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="members.php?action=edit&id=<?= (int)$r['id'] ?>">Edit</a> <form class="d-inline" method="post" onsubmit="return confirm('Delete this member?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="5" class="text-center py-4 text-secondary">No members found.</td></tr><?php endif; ?></tbody></table></div></div><?php endif; ?><?php require 'includes/footer.php'; ?>
